/**
 * Small brand marks embedded as base64 PNGs so the PDF (pdfkit) and PPTX
 * (pptxgenjs) renderers can stamp them on the report header without doing a
 * filesystem or network read at request time — both run in a Node
 * serverless function where reading arbitrary files under public/ at
 * runtime is not guaranteed to work once deployed (Vercel only bundles
 * what static analysis can trace, and public/ is served separately as
 * static assets, not part of the function bundle).
 *
 * LIONS_LOGO_PNG is the official Lions Clubs International emblem
 * (same artwork as public/logo-lions.png).
 *
 * DISTRICT_LOGO_PNG is a PLACEHOLDER (public/logo-rising-star.png) until
 * the real District 3232 F1 badge artwork is supplied — swap the base64
 * below (or wire up an env-configurable URL fetch) once it is available.
 */
export const LIONS_LOGO_PNG = "";
export const DISTRICT_LOGO_PNG = "";
